"""Shared source/base helpers for mandatory ``autocuda export`` publication."""

from __future__ import annotations

import argparse
import fnmatch
import subprocess
import sys
from pathlib import Path
from urllib.parse import urlsplit


def _autocuda_cli_module():
    import autocuda_cli  # noqa: PLC0415

    return autocuda_cli


def _export_ignore(directory: str, contents: list[str]) -> list[str]:
    """``shutil.copytree`` callback for local-only and binary artifacts."""
    module = _autocuda_cli_module()
    source = Path(directory)
    skipped: list[str] = []
    for name in contents:
        path = source / name
        if path.is_dir() and name in module.EXPORT_EXCLUDE_DIRS:
            skipped.append(name)
            continue
        if any(fnmatch.fnmatch(name, pattern) for pattern in module.EXPORT_EXCLUDE_FILES):
            skipped.append(name)
    return skipped


def _expand_repo_to_url(value: str) -> str:
    """Expand a GitHub slug while preserving full URLs and filesystem paths."""
    if (
        "://" in value
        or value.startswith("git@")
        or value.startswith(("/", "~/", "./", "../"))
        or Path(value).exists()
    ):
        return value
    return f"git@github.com:{value}.git"


def _split_repo_branch(value: str | None) -> tuple[str | None, str]:
    """Parse source ``--repo REPO[@BRANCH]``; the branch defaults to main."""
    if value is None:
        return None, "main"
    if not value:
        raise ValueError("--repo must not be empty")
    if Path(value).exists():
        return value, "main"

    split_at = -1
    if "://" in value:
        parsed = urlsplit(value)
        if "@" in parsed.path:
            split_at = value.rfind("@")
    elif value.startswith("git@"):
        split_at = value.find("@", len("git@"))
    elif "@" in value:
        split_at = value.rfind("@")

    if split_at == -1:
        return value, "main"
    repo = value[:split_at]
    branch = value[split_at + 1 :]
    if not repo:
        raise ValueError("--repo must include a repository before @branch")
    if not branch:
        raise ValueError("--repo @branch suffix must name a branch")
    return repo, branch


def _unshallow_if_needed(repo: Path, push_remote: str) -> None:
    """Best-effort unshallowing prevents invalid thin packs on publication."""
    try:
        is_shallow = subprocess.check_output(
            ["git", "-C", str(repo), "rev-parse", "--is-shallow-repository"],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except subprocess.CalledProcessError:
        return
    if is_shallow != "true":
        return
    try:
        remotes_out = subprocess.check_output(
            ["git", "-C", str(repo), "remote"],
            text=True,
            stderr=subprocess.DEVNULL,
        )
    except subprocess.CalledProcessError:
        return
    remotes = [remote.strip() for remote in remotes_out.splitlines() if remote.strip()]
    fetch_from = "upstream" if "upstream" in remotes else push_remote
    print(
        f"shallow clone detected — fetching --unshallow from `{fetch_from}` before push",
        file=sys.stderr,
    )
    subprocess.run(
        ["git", "-C", str(repo), "fetch", fetch_from, "--unshallow"],
        check=False,
    )


def cmd_export(args: argparse.Namespace) -> int:
    """Run the active incremental exporter with mandatory publication."""
    from _cli_extension_incremental_export import cmd_export as incremental_export  # noqa: PLC0415

    return incremental_export(args)
